{"Channel": {"name": "bug-fionabrown-CollaborateForce", "channelID": "ch-force-ae9183"}, "Message": {"User": {"userId": "eid_ab6f41bc", "timestamp": "2026-12-17T17:00:00", "text": "Thanks, @eid_7fba1318! Let's keep communication open as you work through these. Feel free to ask questions or share updates here. Let's get these resolved for our customers! 💪", "utterranceID": "20261217-7-cdb67"}, "Reactions": []}, "ThreadReplies": [], "id": "20261217-7-cdb67"}
