{"Channel": {"name": "develop-hannahsmith-CollaborateForce", "channelID": "ch-force-ce946d"}, "Message": {"User": {"userId": "eid_b7a6e7f9", "timestamp": "2026-09-08T15:12:00", "text": "Hi team, I've noticed some issues with the recent PR#20 that was merged. It seems to be causing some bugs in the application. Can we discuss whether we should revert it?", "utterranceID": "20260908-0-a5108"}, "Reactions": []}, "ThreadReplies": [], "id": "20260908-0-a5108"}
