{"Channel": {"name": "develop-hannahsmith-CollaborateForce", "channelID": "ch-force-ce946d"}, "Message": {"User": {"userId": "eid_839e5084", "timestamp": "2026-09-08T15:21:00", "text": "I've also noticed that some endpoints are returning incorrect data formats. This could be a major issue for clients relying on our API.", "utterranceID": "20260908-3-6d4a4"}, "Reactions": []}, "ThreadReplies": [], "id": "20260908-3-6d4a4"}
