{"Channel": {"name": "planning-ContentRecommender", "channelID": "ch-ender-33b51f"}, "Message": {"User": {"userId": "eid_5af96a7d", "timestamp": "2026-03-01T12:51:00", "text": "Hi team, I want to discuss the Market Research Report for ContentRecommender. Let's brainstorm some ideas and outline the key sections we need to include. 😊", "utterranceID": "20260301-0-d0151"}, "Reactions": []}, "ThreadReplies": [], "id": "20260301-0-d0151"}
