{"Channel": {"name": "bug-iansmith-ContextForce", "channelID": "ch-force-5ff1be"}, "Message": {"User": {"userId": "eid_82e9fcef", "timestamp": "2027-01-09T23:17:00", "text": "Great news, @eid_92c62291! Can you explain what was causing the latency?", "utterranceID": "20270109-1-925f3"}, "Reactions": []}, "ThreadReplies": [], "id": "20270109-1-925f3"}
