{"Channel": {"name": "bug-iansmith-ContextForce", "channelID": "ch-force-5ff1be"}, "Message": {"User": {"userId": "eid_5782059f", "timestamp": "2027-03-26T01:24:00", "text": "Hey Charlie, could you elaborate on why it doesn't need fixing? The error seemed to be blocking access for some third-party apps.", "utterranceID": "20270325-1-248a7"}, "Reactions": []}, "ThreadReplies": [], "id": "20270325-1-248a7"}
