{"Channel": {"name": "bug-juliamartinez-EdgeForce", "channelID": "ch-force-7bfbef"}, "Message": {"User": {"userId": "eid_2347b567", "timestamp": "2027-02-14T17:28:00", "text": "Same here, I'll update once I have a patch for the security issue. 🔧", "utterranceID": "20270214-9-cb5b7"}, "Reactions": []}, "ThreadReplies": [], "id": "20270214-9-cb5b7"}
