{"Channel": {"name": "bug-alicedavis-FlowForce", "channelID": "ch-force-fbc815"}, "Message": {"User": {"userId": "eid_e5e36dc1", "timestamp": "2026-09-12T03:58:00", "text": "Hi team, I found some interesting open-source bugs that might help us with our current Salesforce issues. Let's take a look at them! 😊", "utterranceID": "20260911-0-5fdc7"}, "Reactions": []}, "ThreadReplies": [], "id": "20260911-0-5fdc7"}
