{"Channel": {"name": "bug-fionadavis-InsightForce", "channelID": "ch-force-36f287"}, "Message": {"User": {"userId": "eid_63ea0ec4", "timestamp": "2026-11-10T19:25:00", "text": "Yes, David. I recommend adding a note about the performance expectations with large datasets to help manage user expectations.", "utterranceID": "20261110-8-0f0e1"}, "Reactions": []}, "ThreadReplies": [], "id": "20261110-8-0f0e1"}
