{"Channel": {"name": "planning-AIX", "channelID": "ch-g-aix-f0202d"}, "Message": {"User": {"userId": "eid_88e74382", "timestamp": "2026-03-30T16:54:00", "text": "Hi team, QA team found some issues in the last release of AIX. The report came from QA Specialist eid_ddbe5577.", "utterranceID": "20260418-0-f333a"}, "Reactions": []}, "ThreadReplies": [], "id": "20260418-0-f333a"}
{"Channel": {"name": "planning-AIX", "channelID": "ch-g-aix-f0202d"}, "Message": {"User": {"userId": "eid_4f30e22e", "timestamp": "2026-03-30T16:58:00", "text": "Thanks for the update, Charlie Davis. What exactly did they find?", "utterranceID": "20260418-1-98119"}, "Reactions": []}, "ThreadReplies": [], "id": "20260418-1-98119"}
