{"Channel": {"name": "planning-pAIX", "channelID": "ch--paix-374b62"}, "Message": {"User": {"userId": "slack_admin_bot", "timestamp": "2026-07-05T07:03:00", "text": "@eid_71a4de1d, @eid_31ca5b45 joined planning-pAIX.", "utterranceID": "20260705-12-42799"}, "Reactions": []}, "ThreadReplies": [], "id": "20260705-12-42799"}
{"Channel": {"name": "planning-pAIX", "channelID": "ch--paix-374b62"}, "Message": {"User": {"userId": "eid_71a4de1d", "timestamp": "2026-07-05T16:55:00", "text": "Hi team, QA team found some issues in the last release of pAIX. The report came from QA Specialist eid_88e74382.", "utterranceID": "20260704-0-f954a"}, "Reactions": []}, "ThreadReplies": [], "id": "20260704-0-f954a"}
