{"Channel": {"name": "planning-SalesforceAISearch", "channelID": "ch-earch-52b890"}, "Message": {"User": {"userId": "eid_374a009b", "timestamp": "2026-09-19T12:56:00", "text": "Thanks, team! I'll set up a shared doc for everyone to add their sections. Let's make this document comprehensive and clear. 🚀", "utterranceID": "20260919-14-33e50"}, "Reactions": []}, "ThreadReplies": [], "id": "20260919-14-33e50"}
