{"Channel": {"name": "planning-SalesforceAISearch", "channelID": "ch-earch-52b890"}, "Message": {"User": {"userId": "eid_52681a26", "timestamp": "2026-09-23T23:36:00", "text": "Great points, everyone! Let's assign some action items. @eid_719a0253, can you draft the architecture overview by next Wednesday?", "utterranceID": "20260923-8-ba9c8"}, "Reactions": []}, "ThreadReplies": [], "id": "20260923-8-ba9c8"}
