{"Channel": {"name": "bug-juliataylor-SearchForce", "channelID": "ch-force-1897c0"}, "Message": {"User": {"userId": "eid_13786f09", "timestamp": "2027-04-01T15:05:00", "text": "Hi team, the bug titled 'Inefficient Query Optimization' has been resolved. 🎉", "utterranceID": "20270401-0-bb00a"}, "Reactions": []}, "ThreadReplies": [], "id": "20270401-0-bb00a"}
