{"Channel": {"name": "bug-iansmith-TrendForce", "channelID": "ch-force-c56b63"}, "Message": {"User": {"userId": "eid_5782059f", "timestamp": "2026-07-29T15:20:00", "text": "Great news, @eid_01942cf0! Can you explain what caused the issue?", "utterranceID": "20260729-1-fcc40"}, "Reactions": []}, "ThreadReplies": [], "id": "20260729-1-fcc40"}
