{"Channel": {"name": "planning-ContentForce-PM", "channelID": "ch-ix-pm-6f4188"}, "Message": {"User": {"userId": "eid_40589c87", "timestamp": "2026-03-15T11:23:00", "text": "I'm interested in the analytics dashboard. How comprehensive is it in terms of tracking content engagement and effectiveness?", "utterranceID": "20260611-7-b3682"}, "Reactions": []}, "ThreadReplies": [], "id": "20260611-7-b3682"}
