{"Channel": {"name": "bug-hannahmiller-PitchForce", "channelID": "ch-force-42e4a3"}, "Message": {"User": {"userId": "eid_932ce89c", "timestamp": "2027-01-09T07:58:00", "text": "Will do! If I need any additional info, I'll reach out. Let's get these sorted out. 💪", "utterranceID": "20270109-8-a4098"}, "Reactions": []}, "ThreadReplies": [], "id": "20270109-8-a4098"}
