{"Channel": {"name": "develop-emmamartinez-ProposalForce", "channelID": "ch-force-888914"}, "Message": {"User": {"userId": "eid_a091a47d", "timestamp": "2027-03-16T23:08:00", "text": "First up, we have Nextcloud's Real-time File Sync. This feature allows files to sync in real-time between local devices and the Nextcloud server. You can check it out here: https://github.com/nextcloud/server/pull/2869. Thoughts? @eid_5549aeb7", "utterranceID": "20270316-1-0168f"}, "Reactions": []}, "ThreadReplies": [], "id": "20270316-1-0168f"}
