{"Channel": {"name": "develop-emmamartinez-ProposalForce", "channelID": "ch-force-888914"}, "Message": {"User": {"userId": "eid_8df92d08", "timestamp": "2027-02-11T05:48:00", "text": "Hi team, please check my PR for implementing local data storage for offline access: https://github.com/salesforce/ProposalForce/pull/3. This includes setting up SQLite for both iOS and Android. Let me know your thoughts! 😊", "utterranceID": "20270215-0-61bbe"}, "Reactions": []}, "ThreadReplies": [], "id": "20270215-0-61bbe"}
