{"Channel": {"name": "develop-davidgarcia-SearchFlow", "channelID": "ch-hflow-08262e"}, "Message": {"User": {"userId": "eid_e3c15ff5", "timestamp": "2026-06-13T21:32:00", "text": "Given these issues, should we consider reverting the PR until we have a fix? We don't want to disrupt user experience.", "utterranceID": "20260613-5-6f694"}, "Reactions": []}, "ThreadReplies": [], "id": "20260613-5-6f694"}
