{"Channel": {"name": "bug-juliagarcia-ProposalForce", "channelID": "ch-force-50248b"}, "Message": {"User": {"userId": "eid_8df92d08", "timestamp": "2027-06-09T12:56:00", "text": "Hi team, I found some interesting bugs in popular open-source projects that might help us with our current issues. Let's take a look at them! 😊", "utterranceID": "20270609-0-d9108"}, "Reactions": []}, "ThreadReplies": [], "id": "20270609-0-d9108"}
