{"Channel": {"name": "planning-ProposalForce-PM", "channelID": "ch-ix-pm-1c9c3d"}, "Message": {"User": {"userId": "eid_32ff39b2", "timestamp": "2027-01-03T22:10:00", "text": "Hey @eid_85a4de81, the AI-driven proposal customization sounds interesting. How sophisticated is their AI in terms of adapting to different industries?", "utterranceID": "20270121-1-40112"}, "Reactions": []}, "ThreadReplies": [], "id": "20270121-1-40112"}
