{"Channel": {"name": "bug-emmamiller-SentimentForce", "channelID": "ch-force-664c13"}, "Message": {"User": {"userId": "eid_d96fb219", "timestamp": "2026-12-19T07:43:00", "text": "Agreed, great work @eid_13cb0e90! Let us know if there's anything else we need to test on our end.", "utterranceID": "20261219-6-92fcf"}, "Reactions": []}, "ThreadReplies": [], "id": "20261219-6-92fcf"}
