{"Channel": {"name": "bug-alicemartinez-ConnectForce", "channelID": "ch-force-c583cf"}, "Message": {"User": {"userId": "eid_294ba09d", "timestamp": "2026-08-30T10:01:00", "text": "Hi team, several customers are reporting issues with ConnectForce that we need to address ASAP. Let's go through them one by one. 🚀", "utterranceID": "20260829-0-378e0"}, "Reactions": []}, "ThreadReplies": [], "id": "20260829-0-378e0"}
