{"Channel": {"name": "bug-alicetaylor-MonitorForce", "channelID": "ch-force-7ef125"}, "Message": {"User": {"userId": "eid_5b9ab912", "timestamp": "2026-07-24T20:27:00", "text": "Thanks for the update, Ian. How did you manage to fix it?", "utterranceID": "20260724-3-43121"}, "Reactions": []}, "ThreadReplies": [], "id": "20260724-3-43121"}
