{"Channel": {"name": "bug-bobbrown-CollaborateForce", "channelID": "ch-force-a5e3e1"}, "Message": {"User": {"userId": "eid_d3a4fc8f", "timestamp": "2027-02-06T02:52:00", "text": "Hi team, several customers are reporting issues with CollaborateForce that need our attention. Let's go through them one by one. 😊", "utterranceID": "20270205-0-76fbf"}, "Reactions": []}, "ThreadReplies": [], "id": "20270205-0-76fbf"}
{"Channel": {"name": "bug-bobbrown-CollaborateForce", "channelID": "ch-force-a5e3e1"}, "Message": {"User": {"userId": "eid_d3a4fc8f", "timestamp": "2027-02-06T02:55:00", "text": "First up, we have a 'Token Expiry Mismatch' issue. External applications are experiencing unexpected token expiry, causing authentication failures during API requests. This affects the API Authentication Layer and is impacting CUST-0049. @eid_86f94a48, this one's for you.", "utterranceID": "20270205-1-7283a"}, "Reactions": []}, "ThreadReplies": [], "id": "20270205-1-7283a"}
