{"Channel": {"name": "planning-EF_AIX", "channelID": "ch-f_aix-30c6d3"}, "Message": {"User": {"userId": "eid_9db3abf4", "timestamp": "2026-08-31T20:37:00", "text": "Hi team, QA team found some issues in the last release of EF_AIX reported by QA Specialist eid_7f22371d. Let's discuss.", "utterranceID": "20260825-0-06305"}, "Reactions": []}, "ThreadReplies": [], "id": "20260825-0-06305"}
