{"Channel": {"name": "bug-georgegarcia-InsightForce", "channelID": "ch-force-e800ec"}, "Message": {"User": {"userId": "eid_0c373165", "timestamp": "2026-10-28T16:42:00", "text": "Hi team, I've found some interesting open-source bugs that might help us with our current Salesforce issues. Let's take a look at them! 😊", "utterranceID": "20261028-0-0b38e"}, "Reactions": []}, "ThreadReplies": [], "id": "20261028-0-0b38e"}
