{"Channel": {"name": "bug-emmamiller-SentimentForce", "channelID": "ch-force-664c13"}, "Message": {"User": {"userId": "eid_4df5d4b7", "timestamp": "2026-09-22T10:09:00", "text": "Hi team, I looked into the reported issue about the 'Malformed JSON Response Parsing'.", "utterranceID": "20260921-0-c43da"}, "Reactions": []}, "ThreadReplies": [], "id": "20260921-0-c43da"}
